#include <bits/stdc++.h>
using namespace std;

int N;
vector<vector<int>> adj;

// DFS returns the length from node to the deepest uncovered leaf in its subtree.
// 'limit' is the max allowed path length B.
// 'cnt' counts the number of paths used.
int dfs(int u, int p, int limit, int &cnt) {
    vector<int> depths;
    for (int v : adj[u]) {
        if (v == p) continue;
        int d = dfs(v, u, limit, cnt);
        if (d >= 0) depths.push_back(d + 1);
    }
    sort(depths.rbegin(), depths.rend());
    // Greedy: if two deepest exceed limit, cut.
    while (depths.size() >= 2 && depths[0] + depths[1] > limit) {
        cnt++;
        depths.erase(depths.begin());
    }
    if (depths.empty()) return 0;
    if (depths[0] > limit) {
        cnt++;
        return 0;
    }
    return depths[0];
}

int neededPaths(int limit) {
    int cnt = 0;
    int rem = dfs(0, -1, limit, cnt);
    if (rem > 0) cnt++;
    return cnt;
}

