    }

    // Find minimal A by binary search over B
    int bestA = N, bestB = N;
    int lo = 0, hi = N;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int paths = neededPaths(mid);
        if (paths < bestA || (paths == bestA && mid < bestB)) {
            bestA = paths;
            bestB = mid;
        }
        if (paths <= 1) {
