#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    // We need the lexicographically smallest (A, B):
    // 1) minimize A
    // 2) among them, minimize B
    //
    // A tree can be covered by A paths iff there are at most 2A odd-degree vertices.
    // Minimum A = max(1, #odd / 2) for N>=1.
    //
    // For this minimum A, we need the minimum possible maximum length B among such a decomposition.
    //
    // Root the tree. Let terminals be:
    // - every odd-degree vertex
    // - and if #odd == 0, choose one arbitrary vertex twice conceptually, which means A=1.
    //
    // More generally, for a fixed B, we check whether the tree can be decomposed into at most A paths
    // each of length <= B.
    //
    // Since A is already minimum (= max(1, odd/2)), "at most A" is equivalent to exactly pairing up
    // all required path endpoints. Standard tree DP:
    //
    // DFS returns the length of one unmatched path-end segment going upward, or impossible.
    // At each node, child contributions x mean there is an unmatched segment of length x ending at child,
    // which becomes x+1 at current node.
    //
    // If deg(v) is odd, v must be an endpoint once; if even, not an endpoint.
    // Root parity is handled similarly, but no upward edge exists.
    //
    // We greedily pair child segments so that sums <= B; depending on parity, one segment may remain
    // unmatched (or node itself can serve as endpoint).
    //
    // Simpler formulation:
    // Let need(v) = deg(v)%2. For a rooted subtree, we must leave upward exactly parity of odd terminals
    // in subtree modulo 2, represented by one open segment.
    //
    // DP value = minimum possible open segment length left upward, impossible if none.
    // To test feasibility for fixed B, use multiset pairing greedily with binary search on leftover.
    //
    // This is the classic "minimum path decomposition max length" on tree with prescribed odd endpoints.

    int odd = 0;
    vector<int> deg(N + 1);
    for (int i = 1; i <= N; i++) {
        deg[i] = (int)g[i].size();
        if (deg[i] % 2) odd++;
    }

    int A = max(1, odd / 2);

    if (N == 1) {
        cout << 1 << " " << 0 << "\n";
        return 0;
    }

    vector<int> parent(N + 1, 0), order;
    order.reserve(N);
    {
        stack<int> st;
        st.push(1);
        parent[1] = -1;
        while (!st.empty()) {
            int v = st.top();
            st.pop();
            order.push_back(v);
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                st.push(to);
            }
        }
    }

    auto feasible = [&](int B) -> bool {
        const int INF = 1e9;
        vector<int> dp(N + 1, INF);

        for (int it = N - 1; it >= 0; it--) {
            int v = order[it];
            vector<int> vals;
            bool bad = false;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                if (dp[to] == INF) {
                    bad = true;
                    break;
                }
                if (dp[to] + 1 > B) {
                    bad = true;
                    break;
                }
                vals.push_back(dp[to] + 1);
            }
            if (bad) {
                dp[v] = INF;
                continue;
            }

            // Need parity of open segments after processing children and possibly using v as endpoint.
            // For non-root:
            //   if deg(v) odd -> subtree should leave 0 open from children after possibly endpoint at v? Actually
            //   one endpoint at v toggles parity, so required leftover count among child-segments is 0.
            //   if deg(v) even -> required leftover count among child-segments is 1.
            //
            // More directly, the number of terminals in subtree excluding upward side has parity:
            // odd terminals contributed by descendants + (deg(v)%2).
            // So upward open existence parity = subtree terminal parity.
            //
            // Standard local rule:
            // target leftover count among vals after pairing:
            //   rem = deg(v)%2 ^ 1 for non-root? Let's derive by examples:
            // leaf deg=1 odd, non-root: should return 0 upward (path endpoint at leaf, segment length 0).
            // vals empty => leftover chosen should be 0, so rem=0 for odd.
            // path middle deg=2 even with one child in rooted tree: should pass child's open upward, so rem=1 for even.
            // Thus non-root rem = (deg(v)%2==0 ? 1 : 0).
            //
            // For root:
            // if odd>0, root cannot pass upward, so all must be paired, and if deg(root) odd it itself is endpoint.
            // Thus rem=0 always at root, but root endpoint effect is already inherent because deg parity changes needed pairing.
            // Testing examples confirms using root-rem = (deg(root)%2 ? 1 : 0) would be wrong.
            //
            // Easier method: introduce virtual parent edge for root only when odd==0? Too messy.
            //
            // We instead use terminal model:
            // child vals are open segments ending at terminals in child subtrees.
            // At node v, if deg(v) odd, v itself is a terminal of length 0.
            // We need to pair all terminals inside subtree, except for one terminal that may connect upward
            // if parent edge exists. So:
            // - non-root: multiset = child vals + (0 if deg(v) odd). Leave exactly one unpaired.
            // - root:    multiset = child vals + (0 if deg(v) odd). Leave zero unpaired.
            //
            // This is clean.

            if (deg[v] % 2 == 1) vals.push_back(0);
            sort(vals.begin(), vals.end());

            auto can_with_leftover = [&](int idx) -> bool {
                // idx = index of leftover element, or -1 for none
                vector<int> arr;
                arr.reserve(vals.size());
                for (int i = 0; i < (int)vals.size(); i++) {
                    if (i != idx) arr.push_back(vals[i]);
                }
                int l = 0, r = (int)arr.size() - 1;
                while (l < r) {
                    if (arr[l] + arr[r] > B) return false;
                    l++;
                    r--;
                }
                return true;
            };

            if (v == 1) {
                if ((int)vals.size() % 2 == 1) {
                    dp[v] = INF;
                } else {
                    dp[v] = can_with_leftover(-1) ? 0 : INF;
                }
            } else {
                if ((int)vals.size() % 2 == 0) {
                    // Need exactly one leftover.
                    // Find minimum possible leftover length.
                    int best = INF;

                    // Since pairing smallest with largest is optimal, to test leaving vals[i],
                    // we can brute-force with two pointers in O(k). Total could be O(N^2) in star.
                    // Use binary-search-like observation is tricky; but N constraints in AtCoder for this
                    // problem allow O(N log^2 N)? We need safer.
                    //
                    // We'll use prefix/suffix feasibility for adjacent pairing after removal.
                    int m = vals.size();
                    if (m == 0) {
                        dp[v] = INF;
                    } else {
                        // Precompute pairability of prefixes/suffixes under consecutive pairing in sorted order:
                        // For sorted array, existence of perfect matching with each pair sum<=B
                        // is equivalent to pairing extremes. For array with one removal, remaining sorted array
                        // can be checked by parity-separated adjacent constraints.
                        //
                        // Simpler and still efficient enough for typical constraints? Let's do O(sum deg^2) not safe.
                        //
                        // Alternative:
                        // For removal i, remaining can be perfectly matched iff:
                        // - pairs in [0, i-1] with parity from left adjacent
                        // - pairs in [i+1, m-1] with parity from right adjacent
                        // - and a boundary condition if sides have odd counts.
                        //
                        // Easier: because perfect matching under <=B on sorted list is equivalent to adjacent pairing.
                        // So after removing i, remaining list must satisfy adjacent pair sums <= B.
                        vector<char> pref(m + 1, 0), suf(m + 1, 0);
                        pref[0] = 1;
                        for (int i = 2; i <= m; i += 2) {
                            pref[i] = pref[i - 2] && (vals[i - 2] + vals[i - 1] <= B);
                        }
                        suf[m] = 1;
                        for (int i = m - 2; i >= 0; i -= 2) {
                            suf[i] = suf[i + 2] && (vals[i] + vals[i + 1] <= B);
                        }

                        for (int i = 0; i < m; i++) {
                            int left = i;
                            int right = m - 1 - i;
                            if (left % 2 == 1 || right % 2 == 1) continue;
                            bool ok = pref[left] && suf[i + 1];
                            if (!ok) continue;
                            // Need cross-boundary consistency when both sides exist and left part odd? not needed since even-even.
                            // However adjacency shifts after removal, so boundary between left and right may create a cross pair.
                            // The above is insufficient.
                        }

                        // Fall back to O(m) two-pointer per node using deque-like simulation is complex.
                        // Given need for correctness, do multiset greedy with binary search on leftover candidate using recursion.
                        // But here we'll use O(m^2) worst-case; accepted for moderate constraints.
                        for (int i = 0; i < m; i++) {
                            if (can_with_leftover(i)) {
                                best = vals[i];
                                break;
                            }
                        }
                        dp[v] = best;
                    }
                } else {
                    // Need zero leftover.
                    dp[v] = can_with_leftover(-1) ? 0 : INF;
                }
            }
        }

        return dp[1] != INF;
    };

    int low = 0, high = N - 1;
    while (low < high) {
        int mid = (low + high) / 2;
        if (feasible(mid)) high = mid;
        else low = mid + 1;
    }

    cout << A << " " << low << "\n";
    return 0;
}

