        for (int v : adj[u]) {
            if (v == parent) continue;
            int len = dfs(v, u) + 1;
            childLengths.add(len);
        }
        if (childLengths.isEmpty()) return 0;
        Collections.sort(childLengths);
        int keep = 0;
        // Greedy: keep the longest chain that doesn't exceed B
        for (int i = childLengths.size() - 1; i >= 0; i--) {
            if (keep + childLengths.get(i) <= B) {
                keep += childLengths.get(i);
            } else {
                pathCount++;
            }
        }
        return keep;
    }

    static int minPathsForB(int n, int b) {
        B = b;
        pathCount = 0;
        dfs(0, -1);
        return pathCount + 1; // +1 for the root path
    }

